/** 1 = Patient (Patient) 2 = Prescriber (Prescriber) 3 = Pharmacist (Pharmacist) 4 = Pharmacy (Pharmacy) 5 = Staff (InstitutionStaff) 6 = Distribution (Distributor) 7 = Hcp (Healthcare professional) 8 = Carer (Carer) 9 = Other (Other) 10 = ProgramAdmin (Program administrator) */
export enum CommunicatedWith {
    Patient = 1,
    Prescriber = 2,
    Pharmacist = 3,
    Pharmacy = 4,
    Staff = 5,
    Distribution = 6,
    Hcp = 7,
    Carer = 8,
    Other = 9,
    ProgramAdmin = 10,
}

